\begin{align*}
a^3+b^3+c^3&=(a+b+c)^3-3(a+b+c)(ab+bc+ca)+3abc\\
&=0^3-3(0)(ab+bc+ca)+3(17)\\
&=\boxed{51}
\end{align*}
